function applyExpandedPracticeSolutions(papers){
 for(const [id,questions] of Object.entries(papers)){
  const solutions=EXPANDED_PRACTICE_SOLUTIONS[id];
  if(!solutions||solutions.length!==questions.length)throw Error('Incomplete expanded practice solutions: '+id);
  questions.forEach((q,i)=>{
   const s=solutions[i];
   if(q.n!==s.n||q.correct!==s.correct)throw Error('Expanded practice solution mismatch: '+id+' Q'+q.n);
   q.sol=s.sol;
  });
 }
}
